CREATE TABLE whatsapp_contacts (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, phone VARCHAR(20) NOT NULL, profile_name VARCHAR(200) NULL, first_origin JSON NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_contacts_phone_uq (user_id,phone), UNIQUE KEY whatsapp_contacts_owner_uq (id,user_id), CONSTRAINT whatsapp_contacts_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci